<?php
// Upserts the WooCommerce REST API key used by this store's MCP server.
// The key/secret are generated by Helm (Secret <release>-credentials), so the MCP server can read
// them from the same Secret without anyone copying keys out of WP admin.
// WooCommerce stores the consumer key as wc_api_hash(key) and the secret in plain text.

global $wpdb;

$ck = getenv('WOO_CONSUMER_KEY');
$cs = getenv('WOO_CONSUMER_SECRET');
if (!$ck || !$cs) {
    WP_CLI::error('WOO_CONSUMER_KEY and WOO_CONSUMER_SECRET must be set');
}

$user = get_user_by('login', getenv('ADMIN_USER'));
if (!$user) {
    WP_CLI::error('admin user not found');
}

$table = $wpdb->prefix . 'woocommerce_api_keys';
$description = 'woo-mcp (managed by Helm)';
$row = [
    'user_id'         => $user->ID,
    'description'     => $description,
    'permissions'     => 'read_write',
    'consumer_key'    => wc_api_hash($ck),
    'consumer_secret' => $cs,
    'truncated_key'   => substr($ck, -7),
];

$existingId = $wpdb->get_var($wpdb->prepare("SELECT key_id FROM {$table} WHERE description = %s", $description));
if ($existingId) {
    $wpdb->update($table, $row, ['key_id' => (int) $existingId]);
    WP_CLI::log("API key {$existingId} up to date (…{$row['truncated_key']})");
} else {
    $wpdb->insert($table, $row);
    WP_CLI::log("API key {$wpdb->insert_id} created (…{$row['truncated_key']})");
}
